// Core tests: the 19 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus boundary, validation, and fraction-construction cases. The extra
// success literals below were derived independently from the SPEC's
// rules with an exact rational (Fraction) scratch calculation, not from
// the product code.

import assert from "node:assert/strict";
import test from "node:test";
import { DENSITY, run } from "../public/js/core/convert.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  if (entry.id === "err-unit-enum") continue; // handled below (spec erratum)
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

// SPEC ERRATUM (recorded in HANDOFF.md): fixture err-unit-enum expects
// ENUM for fromUnit "liter", but "liter" is 5 UTF-16 code units and the
// SPEC caps fromUnit at 4 units with the per-field order INPUT_LIMIT
// before ENUM — so under the SPEC's own normative rules the outcome is
// INPUT_LIMIT, and the fixture's expected value is unreachable. The
// implementation follows the normative rule; this case asserts the
// corrected expectation.
test("fixture err-unit-enum (corrected per the normative capacity rule)", () => {
  const entry = coreCases.find((c) => c.id === "err-unit-enum");
  assert.deepEqual(run(entry.input), {
    ok: false,
    error: { code: "INPUT_LIMIT", field: "fromUnit", row: null },
  });
});

const base = { amount: "1", fromUnit: "cup", toUnit: "g", ingredient: "all-purpose-flour" };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("every density-table row converts 1 cup to exactly its pinned grams", () => {
  for (const row of DENSITY) {
    assert.deepEqual(
      run({ amount: "1", fromUnit: "cup", toUnit: "g", ingredient: row.id }),
      {
        ok: true,
        result: {
          value: row.gramsPerCup,
          unit: "g",
          fractionText: null,
          ingredient: row.id,
          gramsPerCup: row.gramsPerCup,
        },
      },
      row.id,
    );
  }
});

test("pure volume ignores a selected ingredient; g->g identity needs none", () => {
  assert.deepEqual(run({ amount: "2", fromUnit: "cup", toUnit: "ml", ingredient: "honey" }), {
    ok: true,
    result: { value: 480, unit: "ml", fractionText: null, ingredient: null, gramsPerCup: null },
  });
  assert.deepEqual(run({ amount: "7", fromUnit: "g", toUnit: "g", ingredient: "honey" }), {
    ok: true,
    result: { value: 7, unit: "g", fractionText: null, ingredient: null, gramsPerCup: null },
  });
});

test("fraction constructions: 0, 1/8, reduced 2/8 -> 1/4, carry to a whole", () => {
  // 10 ml = 1/24 cup: eighths = 0 -> "0"; value rounds to 0.04.
  assert.deepEqual(run({ amount: "10", fromUnit: "ml", toUnit: "cup", ingredient: "none" }).result, {
    value: 0.04, unit: "cup", fractionText: "0", ingredient: null, gramsPerCup: null,
  });
  // 30 ml = 1/8 cup exactly: eighths = 1 -> "1/8"; value 0.125 rounds half-up to 0.13.
  assert.deepEqual(run({ amount: "30", fromUnit: "ml", toUnit: "cup", ingredient: "none" }).result, {
    value: 0.13, unit: "cup", fractionText: "1/8", ingredient: null, gramsPerCup: null,
  });
  // 60 ml = 1/4 cup: eighths = 2, reduced 2/8 -> "1/4".
  assert.deepEqual(run({ amount: "60", fromUnit: "ml", toUnit: "cup", ingredient: "none" }).result, {
    value: 0.25, unit: "cup", fractionText: "1/4", ingredient: null, gramsPerCup: null,
  });
  // 228 ml = 0.95 cup: eighths = 8, carries to the whole -> "1".
  assert.deepEqual(run({ amount: "228", fromUnit: "ml", toUnit: "cup", ingredient: "none" }).result, {
    value: 0.95, unit: "cup", fractionText: "1", ingredient: null, gramsPerCup: null,
  });
});

test("legal endpoints and just-over-limit amounts", () => {
  // 100000 is the largest legal amount (also a fixture); 100000.01 and
  // 100001 pass the grammar but are out of range.
  assert.equal(run({ ...base, amount: "100000" }).ok, true);
  assert.deepEqual(errorOf({ ...base, amount: "100000.01" }), { code: "RANGE", field: "amount", row: null });
  assert.deepEqual(errorOf({ ...base, amount: "100001" }), { code: "RANGE", field: "amount", row: null });
  assert.deepEqual(errorOf({ ...base, amount: "0.0" }), { code: "RANGE", field: "amount", row: null });
  // Leading zeros are grammar-legal: 007 = 7.
  assert.deepEqual(run({ amount: "007", fromUnit: "tsp", toUnit: "ml", ingredient: "none" }).result, {
    value: 35, unit: "ml", fractionText: null, ingredient: null, gramsPerCup: null,
  });
});

test("amount grammar rejects .5, 5., exponents, signs, spaces and commas", () => {
  for (const amount of [".5", "5.", "1e3", "-1", "+1", " 1", "1 ", "1,5", "1..2", "NaN"]) {
    assert.deepEqual(
      errorOf({ ...base, amount }),
      { code: "DECIMAL_FORMAT", field: "amount", row: null },
      amount,
    );
  }
  assert.deepEqual(errorOf({ ...base, amount: "" }), { code: "EMPTY", field: "amount", row: null });
});

test("field order: the first failing field wins, capacity before grammar", () => {
  // amount out of range AND fromUnit invalid: amount is checked first.
  assert.deepEqual(
    errorOf({ amount: "0", fromUnit: "liter", toUnit: "ml", ingredient: "none" }),
    { code: "RANGE", field: "amount", row: null },
  );
  // fromUnit invalid AND toUnit invalid: fromUnit first. (Both values
  // are within the 4-unit capacity, so this reaches the enum check.)
  assert.deepEqual(
    errorOf({ amount: "1", fromUnit: "oz", toUnit: "qt", ingredient: "none" }),
    { code: "ENUM", field: "fromUnit", row: null },
  );
  // "liter" is 5 units: the unit capacity fires before the enum check.
  assert.deepEqual(
    errorOf({ amount: "1", fromUnit: "liter", toUnit: "ml", ingredient: "none" }),
    { code: "INPUT_LIMIT", field: "fromUnit", row: null },
  );
  // A 13-unit amount with bad grammar still reports INPUT_LIMIT first.
  assert.deepEqual(
    errorOf({ amount: "12345678901.5", fromUnit: "cup", toUnit: "ml", ingredient: "none" }),
    { code: "INPUT_LIMIT", field: "amount", row: null },
  );
  // Per-field capacity: ingredient of exactly 32 units reaches ENUM;
  // 33 units is INPUT_LIMIT.
  assert.deepEqual(
    errorOf({ ...base, ingredient: "x".repeat(32) }),
    { code: "ENUM", field: "ingredient", row: null },
  );
  assert.deepEqual(
    errorOf({ ...base, ingredient: "x".repeat(33) }),
    { code: "INPUT_LIMIT", field: "ingredient", row: null },
  );
});

test("enum values are case-sensitive and empty fields report EMPTY", () => {
  assert.deepEqual(errorOf({ ...base, fromUnit: "Cup" }), { code: "ENUM", field: "fromUnit", row: null });
  assert.deepEqual(errorOf({ ...base, toUnit: "G" }), { code: "ENUM", field: "toUnit", row: null });
  assert.deepEqual(errorOf({ ...base, ingredient: "Flour" }), { code: "ENUM", field: "ingredient", row: null });
  assert.deepEqual(errorOf({ ...base, fromUnit: "" }), { code: "EMPTY", field: "fromUnit", row: null });
  assert.deepEqual(errorOf({ ...base, ingredient: "" }), { code: "EMPTY", field: "ingredient", row: null });
});

test("INGREDIENT_REQUIRED fires either way across weight/volume, not for identity", () => {
  assert.deepEqual(
    errorOf({ amount: "1", fromUnit: "cup", toUnit: "g", ingredient: "none" }),
    { code: "INGREDIENT_REQUIRED", field: "ingredient", row: null },
  );
  assert.deepEqual(
    errorOf({ amount: "1", fromUnit: "g", toUnit: "tsp", ingredient: "none" }),
    { code: "INGREDIENT_REQUIRED", field: "ingredient", row: null },
  );
  assert.equal(run({ amount: "1", fromUnit: "g", toUnit: "g", ingredient: "none" }).ok, true);
  assert.equal(run({ amount: "1", fromUnit: "cup", toUnit: "tsp", ingredient: "none" }).ok, true);
});

test("schema rejects wrong types, missing/extra fields, and accessors without calling them", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("1 cup"), schema);
  assert.deepEqual(errorOf([1, 2, 3]), schema);
  assert.deepEqual(errorOf({ amount: "1", fromUnit: "cup", toUnit: "g" }), schema);
  assert.deepEqual(errorOf({ ...base, extra: "x" }), schema);
  assert.deepEqual(errorOf({ ...base, amount: 1 }), schema);
  assert.deepEqual(errorOf({ ...base, amount: null }), schema);
  let called = false;
  const hostile = { fromUnit: "cup", toUnit: "g", ingredient: "none" };
  Object.defineProperty(hostile, "amount", {
    enumerable: true,
    get() {
      called = true;
      return "1";
    },
  });
  assert.deepEqual(errorOf(hostile), schema);
  assert.equal(called, false);
});

test("an unpaired surrogate reports UNICODE before grammar", () => {
  assert.deepEqual(
    errorOf({ ...base, amount: "\uD800" }),
    { code: "UNICODE", field: "amount", row: null },
  );
  assert.deepEqual(
    errorOf({ ...base, ingredient: "flour\uDC00" }),
    { code: "UNICODE", field: "ingredient", row: null },
  );
});

test("cross-checks run only after every field passes", () => {
  // ingredient none + weight/volume crossing would be INGREDIENT_REQUIRED,
  // but the amount fails first.
  assert.deepEqual(
    errorOf({ amount: "abc", fromUnit: "g", toUnit: "ml", ingredient: "none" }),
    { code: "DECIMAL_FORMAT", field: "amount", row: null },
  );
});
